import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr02105Controller {
  @Post('/paydays/:paydayId/process-voucher')
  @HttpCode(200)
  async processPayrollVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const idText = req.params['paydayId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '지급일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT payday_id AS "paydayId", status, journal_voucher_id AS "journalVoucherId" FROM payday WHERE payday_id = CAST(:paydayId AS bigint) FOR UPDATE',
        { paydayId: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '지급일을 찾을 수 없습니다.');
      }
      const payday = rows[0];
      if (payday.status === '전표처리' || payday.journalVoucherId !== null) {
        throw new ApiError(409, 'VOUCHER_ALREADY_PROCESSED', '이미 전표처리된 지급일입니다.');
      }
      if (payday.status !== '마감') {
        throw new ApiError(409, 'PAYDAY_NOT_CLOSED', '마감되지 않은 급여는 전표처리할 수 없습니다.');
      }
      // 가정: 회계시스템 연계 클라이언트가 없어, 회신된 전표를 journal_voucher 행으로 대신 기록한다.
      // 가정: 전표번호는 'PAY-지급일ID' 형식으로 채번한다.
      const created = await db.query(
        "INSERT INTO journal_voucher (voucher_no, voucher_date, source_type, status, created_at, updated_at) VALUES ('PAY-' || CAST(:paydayId AS text), CAST(now() AS date), 'PAYROLL', '승인', now(), now()) RETURNING journal_voucher_id AS \"journalVoucherId\", voucher_no AS \"voucherNo\"",
        { paydayId: idText },
      );
      await db.execute(
        "UPDATE payday SET status = '전표처리', journal_voucher_id = CAST(:voucherId AS bigint), voucher_processed_at = now(), updated_at = now() WHERE payday_id = CAST(:paydayId AS bigint)",
        { voucherId: created[0].journalVoucherId, paydayId: idText },
      );
      const result = await db.query(
        'SELECT p.payday_id AS "paydayId", p.status AS status, p.journal_voucher_id AS "journalVoucherId", v.voucher_no AS "voucherNo" FROM payday p JOIN journal_voucher v ON v.journal_voucher_id = p.journal_voucher_id WHERE p.payday_id = CAST(:paydayId AS bigint)',
        { paydayId: idText },
      );
      return result[0];
    });
  }
}

