import { useState } from 'react';
import { call, Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, RefName, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02105Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [results, setResults] = useState<Row[]>([]);

  async function submit() {
    if (paydayId === '') {
      throw new Error('급여 지급일을 선택하세요.');
    }
    const res = await call('POST', '/paydays/' + paydayId + '/process-voucher', role, {});
    setResults([res, ...results.filter((r) => r.paydayId !== res.paydayId)]);
    setOpen(false);
    setPaydayId('');
    notify('급여 전표처리를 했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리 건수</h2>
        <Tiles items={[['이번 화면 전표처리', results.length]]} />
      </section>
      <section className="box span-8">
        <h2>전표처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setOpen(true)}>전표처리 요청</button>
        </Band>
        <DataTable
          columns={[
            { key: 'paydayId', label: '급여 지급일', render: (r) => <RefName table="payday" role={role} value={r.paydayId} /> },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r.status} /> },
            { key: 'voucherNo', label: '전표번호' },
          ]}
          rows={results}
          empty="처리한 전표가 없습니다."
        />
      </section>
      {open && (
        <Drawer title="급여 전표처리 요청" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="전표처리" note="마감된 급여만 전표처리할 수 있습니다.">
            <Field label="급여 지급일" required wide>
              <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
